<?php

namespace App\Services;

use App\Models\Role;
use App\Models\User;
use App\Support\DatabaseBackupPolicy;
use Carbon\Carbon;
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Facades\Schema;
use Illuminate\Support\Facades\Storage;
use Illuminate\Support\Str;
use RuntimeException;
use Throwable;

/**
 * Controlled, verified, Admin-only database restoration service.
 *
 * Operates exclusively on verified backup artifacts generated by
 * DatabaseBackupService. Never executes arbitrary uploaded SQL.
 */
class DatabaseRestoreService
{
    public const STATE_PENDING = 'PENDING';
    public const STATE_VALIDATING = 'VALIDATING';
    public const STATE_SAFETY_BACKUP = 'SAFETY_BACKUP';
    public const STATE_RESTORING = 'RESTORING';
    public const STATE_VERIFYING = 'VERIFYING';
    public const STATE_COMPLETED = 'COMPLETED';
    public const STATE_FAILED = 'FAILED';
    public const STATE_RECOVERY_REQUIRED = 'RECOVERY_REQUIRED';

    /** True while restore() is executing in the current PHP process. */
    public static bool $inProcessRestoreActive = false;

    private string $directory = 'backups';

    public function __construct(private DatabaseBackupService $backupService)
    {
    }

    /**
     * Return the latest persisted restore state, if any.
     *
     * @return array<string,mixed>|null
     */
    public function currentState(): ?array
    {
        $path = $this->absolutePath($this->directory . '/restore-state.json');
        if (is_link($path) || !is_file($path)) {
            return null;
        }

        $raw = @file_get_contents($path);
        if ($raw === false) {
            return null;
        }

        $decoded = json_decode($raw, true);

        return is_array($decoded) ? $decoded : null;
    }

    public function isMaintenanceActive(): bool
    {
        $flag = $this->absolutePath($this->directory . '/restore-maintenance.flag');

        return !is_link($flag) && is_file($flag);
    }

    public function isRestoreActivelyRunning(): bool
    {
        $state = $this->currentState();

        return ($state['state'] ?? null) === self::STATE_RESTORING
            && $this->backupService->isOperationLockHeld();
    }

    /**
     * Detect a crashed/interrupted restore (maintenance flag active and state
     * stuck in RESTORING, but backup.lock is no longer held) and transition
     * it to RECOVERY_REQUIRED.
     *
     * @return array<string,mixed>|null
     */
    public function detectInterruptedRestore(): ?array
    {
        $state = $this->currentState();
        if (!$this->isMaintenanceActive() || !is_array($state)) {
            return $state;
        }

        if (($state['state'] ?? null) === self::STATE_RESTORING && !$this->backupService->isOperationLockHeld()) {
            $transitions = $state['transitions'] ?? [];
            $transitions[] = [
                'state' => self::STATE_RECOVERY_REQUIRED,
                'at' => Carbon::now('Asia/Manila')->toIso8601String(),
            ];
            $state['state'] = self::STATE_RECOVERY_REQUIRED;
            $state['completed_at'] = Carbon::now('Asia/Manila')->toIso8601String();
            $state['failure_category'] = 'interrupted_during_restore';
            $state['error_message'] = 'Previous restore process terminated unexpectedly before completion. Recovery is required.';
            $state['transitions'] = $transitions;
            $this->persistState($state);
        }

        return $state;
    }

    /**
     * Check whether database-backed authentication and sessions are usable
     * during recovery mode.
     */
    public function canAuthenticateDuringRecovery(): bool
    {
        try {
            return Schema::hasTable('users') && Schema::hasTable('sessions');
        } catch (Throwable) {
            return false;
        }
    }

    /**
     * Restore the currently configured MySQL application database from an
     * existing verified backup artifact.
     *
     * @return array<string,mixed>
     */
    public function restore(string $backupId, ?User $actor = null): array
    {
        return $this->backupService->withOperationLock(function () use ($backupId, $actor) {
            return $this->restoreInternal($backupId, $actor);
        }, 'Another database backup or restore operation is already running. Please try again shortly.');
    }

    /**
     * Parse and strictly validate a backup SQL file against DatabaseBackupPolicy.
     *
     * @return array{create:array<string,string>, inserts:array<int,string>, row_counts:array<string,int>}
     */
    public function parseAndValidateSql(string $sql): array
    {
        $statements = $this->splitSqlStatements($sql);
        $allowedTables = DatabaseBackupPolicy::allTables();
        $dataTables = DatabaseBackupPolicy::DATA_TABLES;

        $creates = [];
        $inserts = [];
        $rowCounts = array_fill_keys($allowedTables, 0);

        foreach ($statements as $stmt) {
            $trimmed = trim($stmt);
            if ($trimmed === '') {
                continue;
            }

            if (preg_match('/^CREATE\s+TABLE\s+`([A-Za-z0-9_]+)`\s*\(/i', $trimmed, $m) === 1) {
                $table = $m[1];
                if (!in_array($table, $allowedTables, true)) {
                    throw new RuntimeException("Unexpected table identifier in CREATE TABLE: {$table}.");
                }
                if (isset($creates[$table])) {
                    throw new RuntimeException("Duplicate CREATE TABLE statement for {$table}.");
                }
                $creates[$table] = $trimmed;
                continue;
            }

            if (preg_match('/^INSERT\s+INTO\s+`([A-Za-z0-9_]+)`\s*\(/i', $trimmed, $m) === 1) {
                $table = $m[1];
                if (!in_array($table, $dataTables, true)) {
                    throw new RuntimeException("Disallowed INSERT INTO table: {$table}.");
                }
                $inserts[] = $trimmed;
                $rowCounts[$table]++;
                continue;
            }

            throw new RuntimeException('Unrecognized or disallowed SQL statement in backup artifact.');
        }

        foreach ($allowedTables as $table) {
            if (!isset($creates[$table])) {
                throw new RuntimeException("Backup SQL is missing CREATE TABLE for {$table}.");
            }
        }

        return [
            'create' => $creates,
            'inserts' => $inserts,
            'row_counts' => $rowCounts,
        ];
    }

    /**
     * Validate that the backup manifest conforms to the approved Phase 1 policy.
     */
    public function validateManifestPolicy(array $manifest): void
    {
        if ((int) ($manifest['format_version'] ?? 0) !== DatabaseBackupPolicy::FORMAT_VERSION) {
            throw new RuntimeException('Unsupported backup format version.');
        }
        if ((int) ($manifest['manifest_version'] ?? 0) !== DatabaseBackupPolicy::MANIFEST_VERSION) {
            throw new RuntimeException('Unsupported backup manifest version.');
        }
        if (($manifest['verification_status'] ?? '') !== 'verified') {
            throw new RuntimeException('Backup verification status is not verified.');
        }
        if (empty($manifest['source_database'])) {
            throw new RuntimeException('Backup manifest is missing source database identity.');
        }

        $expectedAll = DatabaseBackupPolicy::allTables();
        $expectedData = DatabaseBackupPolicy::DATA_TABLES;
        $expectedStructure = DatabaseBackupPolicy::STRUCTURE_ONLY_TABLES;

        if (($manifest['included_tables'] ?? []) !== $expectedAll
            || ($manifest['data_tables'] ?? []) !== $expectedData
            || ($manifest['structure_only_tables'] ?? []) !== $expectedStructure) {
            throw new RuntimeException('Backup table manifest does not match the approved 38-table policy.');
        }

        $objects = $manifest['objects'] ?? [];
        foreach (['views', 'triggers', 'routines', 'events'] as $kind) {
            if (!empty($objects[$kind])) {
                throw new RuntimeException("Backup contains unsupported database objects ({$kind}).");
            }
        }
    }

    /**
     * Verify the runtime target database identity before any destructive SQL.
     */
    public function verifyTargetDatabase(\PDO $pdo): string
    {
        $configuredDb = trim((string) config('database.connections.mysql.database', ''));
        $driver = (string) $pdo->getAttribute(\PDO::ATTR_DRIVER_NAME);
        if ($driver !== 'mysql') {
            throw new RuntimeException('Database restoration requires a MySQL connection.');
        }

        $stmt = $pdo->query('SELECT DATABASE() AS db');
        $row = $stmt ? $stmt->fetch(\PDO::FETCH_ASSOC) : false;
        if ($stmt) {
            $stmt->closeCursor();
        }
        $selectedDb = trim((string) ($row['db'] ?? ''));

        if ($selectedDb === '') {
            throw new RuntimeException('No target MySQL database is selected.');
        }
        if ($configuredDb === '' || $selectedDb !== $configuredDb) {
            throw new RuntimeException('Target database identity mismatch.');
        }

        return $selectedDb;
    }

    private function restoreInternal(string $backupId, ?User $actor): array
    {
        if (function_exists('set_time_limit')) {
            @set_time_limit(0);
        }

        $restoreId = strtolower(Str::random(16));
        $startedAt = Carbon::now('Asia/Manila')->toIso8601String();
        $transitions = [];
        $safetyBackupId = null;
        $targetDb = null;
        $destructivePhaseEntered = false;

        $transition = function (string $state, array $extra = []) use (
            $restoreId,
            $backupId,
            $actor,
            $startedAt,
            &$transitions,
            &$safetyBackupId,
            &$targetDb
        ): void {
            $transitions[] = [
                'state' => $state,
                'at' => Carbon::now('Asia/Manila')->toIso8601String(),
            ];
            $this->persistState(array_merge([
                'restore_id' => $restoreId,
                'backup_id' => $backupId,
                'actor_id' => $actor?->id,
                'target_database' => $targetDb,
                'safety_backup_id' => $safetyBackupId,
                'state' => $state,
                'started_at' => $startedAt,
                'transitions' => $transitions,
            ], $extra));
        };

        self::$inProcessRestoreActive = true;

        try {
            $transition(self::STATE_PENDING);
            $transition(self::STATE_VALIDATING);

            // 1. Verify backup manifest, SHA-256, HMAC, and policy
            $manifest = $this->backupService->findBackup($backupId);
            $this->validateManifestPolicy($manifest);

            $sqlRelativePath = $this->backupService->downloadPath($backupId);
            $sqlContent = Storage::disk('local')->get($sqlRelativePath);
            if (!is_string($sqlContent) || $sqlContent === '') {
                throw new RuntimeException('Unable to read verified SQL backup content.');
            }

            $parsed = $this->parseAndValidateSql($sqlContent);

            // 2. Verify target MySQL database identity
            $pdo = $this->newMysqlPdo();
            $targetDb = $this->verifyTargetDatabase($pdo);

            $this->safeAuditEvent([
                'event' => 'restore_started',
                'restore_id' => $restoreId,
                'backup_id' => $backupId,
                'target_database' => $targetDb,
                'actor_id' => $actor?->id,
            ]);

            // 3. Automatic pre-restore safety backup (retained even on failure)
            $transition(self::STATE_SAFETY_BACKUP);
            $safetyManifest = $this->backupService->createBackupWithinLock($actor);
            $safetyBackupId = (string) $safetyManifest['backup_id'];
            $this->backupService->findBackup($safetyBackupId);

            // 4. Enable application-wide maintenance flag and run SQL import
            $this->enableMaintenanceMode($restoreId);
            $transition(self::STATE_RESTORING);
            $destructivePhaseEntered = true;

            $this->executeRestoreSql($pdo, $parsed);

            // 5. Post-restore verification
            $transition(self::STATE_VERIFYING);
            $verification = $this->verifyRestoredDatabase($pdo, $manifest, $parsed);

            // 6. Completed — release maintenance mode
            $this->disableMaintenanceMode();
            $completedAt = Carbon::now('Asia/Manila')->toIso8601String();
            $transition(self::STATE_COMPLETED, [
                'completed_at' => $completedAt,
                'verification' => $verification,
            ]);

            $this->safeAuditEvent([
                'event' => 'restore_completed',
                'restore_id' => $restoreId,
                'backup_id' => $backupId,
                'safety_backup_id' => $safetyBackupId,
                'target_database' => $targetDb,
                'actor_id' => $actor?->id,
                'verification' => $verification,
            ]);

            return $this->currentState() ?? [
                'restore_id' => $restoreId,
                'state' => self::STATE_COMPLETED,
                'safety_backup_id' => $safetyBackupId,
                'verification' => $verification,
            ];
        } catch (Throwable $e) {
            $finalState = $destructivePhaseEntered ? self::STATE_RECOVERY_REQUIRED : self::STATE_FAILED;

            if (!$destructivePhaseEntered) {
                $this->disableMaintenanceMode();
            }

            try {
                $transition($finalState, [
                    'completed_at' => Carbon::now('Asia/Manila')->toIso8601String(),
                    'failure_category' => $destructivePhaseEntered ? 'partial_or_verification_failure' : 'pre_restore_validation_or_safety_backup_failure',
                    'error_message' => $e->getMessage(),
                ]);
            } catch (Throwable) {
                // Do not mask the primary restore failure if state persistence fails.
            }

            $this->safeAuditEvent([
                'event' => 'restore_failed',
                'restore_id' => $restoreId,
                'backup_id' => $backupId,
                'safety_backup_id' => $safetyBackupId,
                'target_database' => $targetDb,
                'actor_id' => $actor?->id,
                'final_state' => $finalState,
                'failure_category' => $destructivePhaseEntered ? 'recovery_required' : 'aborted_safely',
                'error' => $e->getMessage(),
            ]);

            throw $e;
        } finally {
            self::$inProcessRestoreActive = false;
        }
    }

    private function executeRestoreSql(\PDO $pdo, array $parsed): void
    {
        $pdo->exec('SET FOREIGN_KEY_CHECKS=0');

        try {
            foreach (array_reverse(DatabaseBackupPolicy::allTables()) as $table) {
                $pdo->exec('DROP TABLE IF EXISTS `' . str_replace('`', '``', $table) . '`');
            }

            foreach (DatabaseBackupPolicy::allTables() as $table) {
                $pdo->exec($parsed['create'][$table]);
            }

            foreach ($parsed['inserts'] as $insertSql) {
                $pdo->exec($insertSql);
            }
        } finally {
            try {
                $pdo->exec('SET FOREIGN_KEY_CHECKS=1');
            } catch (Throwable) {
                // Ensure outer exception is not masked if connection dropped.
            }
        }
    }

    /**
     * @return array<string,bool>
     */
    private function verifyRestoredDatabase(\PDO $pdo, array $manifest, array $parsed): array
    {
        $db = $pdo->quote($this->verifyTargetDatabase($pdo));

        $stmt = $pdo->query("SELECT TABLE_NAME, ENGINE FROM information_schema.TABLES WHERE TABLE_SCHEMA={$db} AND TABLE_TYPE='BASE TABLE' ORDER BY TABLE_NAME");
        $tables = $stmt ? ($stmt->fetchAll(\PDO::FETCH_ASSOC) ?: []) : [];
        if ($stmt) {
            $stmt->closeCursor();
        }

        $objects = [
            'views' => $this->fetchCol($pdo, "SELECT TABLE_NAME FROM information_schema.VIEWS WHERE TABLE_SCHEMA={$db}"),
            'triggers' => $this->fetchCol($pdo, "SELECT TRIGGER_NAME FROM information_schema.TRIGGERS WHERE TRIGGER_SCHEMA={$db}"),
            'routines' => $this->fetchCol($pdo, "SELECT ROUTINE_NAME FROM information_schema.ROUTINES WHERE ROUTINE_SCHEMA={$db}"),
            'events' => $this->fetchCol($pdo, "SELECT EVENT_NAME FROM information_schema.EVENTS WHERE EVENT_SCHEMA={$db}"),
        ];

        $schemaCheck = DatabaseBackupPolicy::checkSchema($tables, $objects);
        if (!$schemaCheck['ok']) {
            throw new RuntimeException('Post-restore schema verification failed.');
        }

        // Verify normalized SHOW CREATE TABLE DDL matches the backup SQL
        foreach (DatabaseBackupPolicy::allTables() as $table) {
            $quoted = '`' . str_replace('`', '``', $table) . '`';
            $ddlStmt = $pdo->query("SHOW CREATE TABLE {$quoted}");
            $ddlRow = $ddlStmt ? $ddlStmt->fetch(\PDO::FETCH_ASSOC) : false;
            if ($ddlStmt) {
                $ddlStmt->closeCursor();
            }
            $actualDdl = (string) ($ddlRow['Create Table'] ?? (is_array($ddlRow) ? (array_values($ddlRow)[1] ?? '') : ''));
            if (DatabaseBackupPolicy::normalizeDdl($actualDdl) !== DatabaseBackupPolicy::normalizeDdl($parsed['create'][$table])) {
                throw new RuntimeException("Post-restore DDL mismatch on table {$table}.");
            }
        }

        // Verify foreign-key referential integrity (MySQL does not validate
        // existing rows when FOREIGN_KEY_CHECKS=1 is re-enabled). Group by
        // CONSTRAINT_NAME so composite foreign keys are verified together.
        $fkStmt = $pdo->query(
            "SELECT CONSTRAINT_NAME, TABLE_NAME, COLUMN_NAME, REFERENCED_TABLE_NAME, REFERENCED_COLUMN_NAME, ORDINAL_POSITION
             FROM information_schema.KEY_COLUMN_USAGE
             WHERE TABLE_SCHEMA={$db} AND REFERENCED_TABLE_NAME IS NOT NULL
             ORDER BY TABLE_NAME, CONSTRAINT_NAME, ORDINAL_POSITION"
        );
        $fkRows = $fkStmt ? ($fkStmt->fetchAll(\PDO::FETCH_ASSOC) ?: []) : [];
        if ($fkStmt) {
            $fkStmt->closeCursor();
        }
        foreach ($this->groupForeignKeysByConstraint($fkRows) as $constraintKey => $fkGroup) {
            $orphanSql = $this->buildFkOrphanCheckSql($fkGroup['table'], $fkGroup['columns'], $fkGroup['referenced_table']);
            $orphanStmt = $pdo->query($orphanSql);
            $orphan = $orphanStmt ? $orphanStmt->fetch(\PDO::FETCH_NUM) : false;
            if ($orphanStmt) {
                $orphanStmt->closeCursor();
            }
            if ($orphan !== false) {
                throw new RuntimeException("Post-restore foreign-key orphan detected on {$constraintKey}.");
            }
        }

        $expectedCounts = $manifest['row_counts'] ?? [];
        foreach (DatabaseBackupPolicy::allTables() as $table) {
            $quoted = '`' . str_replace('`', '``', $table) . '`';
            $cntStmt = $pdo->query("SELECT COUNT(*) AS c FROM {$quoted}");
            $row = $cntStmt ? $cntStmt->fetch(\PDO::FETCH_ASSOC) : false;
            if ($cntStmt) {
                $cntStmt->closeCursor();
            }
            $actualCount = (int) ($row['c'] ?? -1);

            if (!DatabaseBackupPolicy::includesData($table)) {
                if ($actualCount !== 0) {
                    throw new RuntimeException("Structure-only table {$table} unexpectedly contains rows after restore.");
                }
                continue;
            }

            $expected = isset($expectedCounts[$table]) ? (int) $expectedCounts[$table] : ($parsed['row_counts'][$table] ?? 0);
            if ($actualCount !== $expected) {
                throw new RuntimeException("Post-restore row count mismatch on table {$table} (expected {$expected}, got {$actualCount}).");
            }
        }

        // Application model smoke check against the verified MySQL target
        DB::purge('mysql');
        User::on('mysql')->count();
        Role::on('mysql')->count();

        return [
            'sql_import' => true,
            'schema_verification' => true,
            'data_verification' => true,
            'smoke_checks' => true,
        ];
    }

    private function fetchCol(\PDO $pdo, string $sql): array
    {
        $stmt = $pdo->query($sql);
        if (!$stmt) {
            return [];
        }
        try {
            return $stmt->fetchAll(\PDO::FETCH_COLUMN) ?: [];
        } finally {
            $stmt->closeCursor();
        }
    }

    private function splitSqlStatements(string $sql): array
    {
        $statements = [];
        $buffer = '';
        $inString = false;
        $escaped = false;
        $length = strlen($sql);
        $i = 0;

        while ($i < $length) {
            $char = $sql[$i];

            if (!$inString && $char === '-' && ($sql[$i + 1] ?? '') === '-') {
                $newlinePos = strpos($sql, "\n", $i);
                if ($newlinePos === false) {
                    break;
                }
                $i = $newlinePos + 1;
                continue;
            }

            if ($inString) {
                $buffer .= $char;
                if ($escaped) {
                    $escaped = false;
                } elseif ($char === '\\') {
                    $escaped = true;
                } elseif ($char === "'") {
                    if (($sql[$i + 1] ?? '') === "'") {
                        $buffer .= "'";
                        $i++;
                    } else {
                        $inString = false;
                    }
                }
                $i++;
                continue;
            }

            if ($char === "'") {
                $inString = true;
                $buffer .= $char;
                $i++;
                continue;
            }

            if ($char === ';') {
                $trimmed = trim($buffer);
                if ($trimmed !== '') {
                    $statements[] = $trimmed;
                }
                $buffer = '';
                $i++;
                continue;
            }

            $buffer .= $char;
            $i++;
        }

        $trimmed = trim($buffer);
        if ($trimmed !== '') {
            $statements[] = $trimmed;
        }

        return $statements;
    }

    private function newMysqlPdo(): \PDO
    {
        $config = config('database.connections.mysql');
        $dsn = sprintf(
            'mysql:host=%s;port=%s;dbname=%s;charset=%s',
            (string) ($config['host'] ?? '127.0.0.1'),
            (string) ($config['port'] ?? '3306'),
            (string) ($config['database'] ?? ''),
            (string) ($config['charset'] ?? 'utf8mb4')
        );

        return new \PDO($dsn, (string) ($config['username'] ?? ''), (string) ($config['password'] ?? ''), [
            \PDO::ATTR_ERRMODE => \PDO::ERRMODE_EXCEPTION,
            \PDO::ATTR_DEFAULT_FETCH_MODE => \PDO::FETCH_ASSOC,
        ]);
    }

    /**
     * Group information_schema.KEY_COLUMN_USAGE rows by table and constraint
     * name so composite foreign keys are evaluated atomically.
     *
     * @param  array<int,array<string,mixed>>  $rows
     * @return array<string,array{table:string, referenced_table:string, columns:array<int,array{column:string, referenced_column:string}>}>
     */
    public function groupForeignKeysByConstraint(array $rows): array
    {
        $grouped = [];

        foreach ($rows as $row) {
            $table = (string) ($row['TABLE_NAME'] ?? '');
            $constraint = (string) ($row['CONSTRAINT_NAME'] ?? '');
            $key = $table . '.' . $constraint;

            if (!isset($grouped[$key])) {
                $grouped[$key] = [
                    'table' => $table,
                    'referenced_table' => (string) ($row['REFERENCED_TABLE_NAME'] ?? ''),
                    'columns' => [],
                ];
            }

            $grouped[$key]['columns'][] = [
                'column' => (string) ($row['COLUMN_NAME'] ?? ''),
                'referenced_column' => (string) ($row['REFERENCED_COLUMN_NAME'] ?? ''),
            ];
        }

        return $grouped;
    }

    /**
     * Build a single- or multi-column orphan-detection SQL query for a
     * grouped foreign-key constraint.
     *
     * @param  array{table:string, referenced_table:string, columns:array<int,array{column:string, referenced_column:string}>}  $group
     */
    public function buildFkOrphanCheckSql(string $childTable, array $columns, string $referencedTable = ''): string
    {
        if ($referencedTable === '' && isset($columns[0]['referenced_table'])) {
            $referencedTable = (string) $columns[0]['referenced_table'];
        }

        $q = fn (string $id): string => '`' . str_replace('`', '``', $id) . '`';
        $child = $q($childTable);
        $parent = $q($referencedTable);

        $joinParts = [];
        $nonNullParts = [];
        foreach ($columns as $pair) {
            $col = $q($pair['column']);
            $ref = $q($pair['referenced_column']);
            $joinParts[] = "c.{$col} = p.{$ref}";
            $nonNullParts[] = "c.{$col} IS NOT NULL";
        }

        $firstRef = $q($columns[0]['referenced_column']);
        $joinClause = implode(' AND ', $joinParts);
        $nonNullClause = implode(' AND ', $nonNullParts);

        return "SELECT 1 FROM {$child} c LEFT JOIN {$parent} p ON {$joinClause} WHERE {$nonNullClause} AND p.{$firstRef} IS NULL LIMIT 1";
    }

    private function persistState(array $state): void
    {
        $this->ensureDirectory();
        $path = $this->absolutePath($this->directory . '/restore-state.json');
        if (is_link($path)) {
            throw new RuntimeException('Symbolic links are not permitted for restore state.');
        }

        $encoded = json_encode($state, JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES);
        if ($encoded === false) {
            throw new RuntimeException('Unable to encode restore state.');
        }

        $tmp = $this->absolutePath($this->directory . '/restore-state.json.tmp.' . Str::random(8));
        if (@file_put_contents($tmp, $encoded, LOCK_EX) === false || !@rename($tmp, $path)) {
            @unlink($tmp);
            throw new RuntimeException('Unable to persist restore state atomically.');
        }
    }

    private function enableMaintenanceMode(string $restoreId): void
    {
        $this->ensureDirectory();
        $path = $this->absolutePath($this->directory . '/restore-maintenance.flag');
        if (is_link($path)) {
            throw new RuntimeException('Symbolic links are not permitted for restore maintenance flag.');
        }
        if (@file_put_contents($path, $restoreId, LOCK_EX) === false) {
            throw new RuntimeException('Unable to activate restore maintenance guard.');
        }
    }

    private function disableMaintenanceMode(): void
    {
        $flag = $this->absolutePath($this->directory . '/restore-maintenance.flag');
        if (!is_link($flag) && is_file($flag)) {
            @unlink($flag);
        }
    }

    private function safeAuditEvent(array $event): void
    {
        try {
            $this->ensureDirectory();
            $path = $this->absolutePath($this->directory . '/restore-audit.log');
            $handle = @fopen($path, 'ab');
            if ($handle === false) {
                return;
            }
            try {
                if (@flock($handle, LOCK_EX)) {
                    $event['at'] = Carbon::now('Asia/Manila')->toIso8601String();
                    $line = json_encode($event, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES);
                    if ($line !== false) {
                        @fwrite($handle, $line . PHP_EOL);
                        @fflush($handle);
                    }
                }
            } finally {
                @flock($handle, LOCK_UN);
                @fclose($handle);
            }
        } catch (Throwable $e) {
            report($e);
        }
    }

    private function ensureDirectory(): void
    {
        if (!Storage::disk('local')->exists($this->directory)) {
            Storage::disk('local')->makeDirectory($this->directory);
        }
    }

    private function absolutePath(string $path): string
    {
        return Storage::disk('local')->path($path);
    }
}
